478	///                 'record' or 'replay' mode.
479	/// /param SaveOutput Store the device memory after kernel
480	///                   execution on persistent storage.
481	/// /param EmitReport Emit a summary report after the recording.
482	/// /param OutputDirPath The output directory where the record replay files
483	/// should be stored. An empty string or nullptr indicates the current working
484	/// directory should be used.
485	EXTERN int __tgt_activate_record_replay(int64_t DeviceId, uint64_t MemorySize,
486	                                        void *VAddr, bool IsRecord,
487	                                        bool SaveOutput, bool EmitReport,
488	                                        const char *OutputDirPath) {
489	  assert(PM && "Runtime not initialized");
490	  OMPT_IF_BUILT(ReturnAddressSetterRAII RA(__builtin_return_address(0)));
491	  auto DeviceOrErr = PM->getDevice(DeviceId);
492	  if (!DeviceOrErr)
493	    FATAL_MESSAGE(DeviceId, "%s", toString(DeviceOrErr.takeError()).c_str());
494	
495	  int Rc = target_activate_rr(*DeviceOrErr, MemorySize, VAddr, IsRecord,
496	                              SaveOutput, EmitReport, OutputDirPath);
497	  if (Rc != OFFLOAD_SUCCESS) {
498	    ODBG(ODT_Interface) << "Record replay failed to activate in device "
499	                        << DeviceId;
500	    return OMP_TGT_FAIL;
501	  }
502	  return OMP_TGT_SUCCESS;
503	}
