603	EXTERN void __tgt_target_nowait_query(void **AsyncHandle) {
604	  assert(PM && "Runtime not initialized");
605	  OMPT_IF_BUILT(ReturnAddressSetterRAII RA(__builtin_return_address(0)));
606	
607	  if (!AsyncHandle || !*AsyncHandle) {
608	    FATAL_MESSAGE0(
609	        1, "Receive an invalid async handle from the current OpenMP task. Is "
610	           "this a target nowait region?\n");
611	  }
612	
613	  // Exponential backoff tries to optimally decide if a thread should just query
614	  // for the device operations (work/spin wait on them) or block until they are
615	  // completed (use device side blocking mechanism). This allows the runtime to
616	  // adapt itself when there are a lot of long-running target regions in-flight.
617	  static thread_local utils::ExponentialBackoff QueryCounter(
618	      Int64Envar("OMPTARGET_QUERY_COUNT_MAX", 10),
619	      Int64Envar("OMPTARGET_QUERY_COUNT_THRESHOLD", 5),
620	      Envar<float>("OMPTARGET_QUERY_COUNT_BACKOFF_FACTOR", 0.5f));
621	
622	  auto *AsyncInfo = (AsyncInfoTy *)*AsyncHandle;
623	
624	  // If the thread is actively waiting on too many target nowait regions, we
625	  // should use the blocking sync type.
626	  if (QueryCounter.isAboveThreshold())
627	    AsyncInfo->SyncType = AsyncInfoTy::SyncTy::BLOCKING;
628	
629	  if (AsyncInfo->synchronize())
630	    FATAL_MESSAGE0(1, "Error while querying the async queue for completion.\n");
631	  // If there are device operations still pending, return immediately without
632	  // deallocating the handle and increase the current thread query count.
633	  if (!AsyncInfo->isDone()) {
634	    QueryCounter.increment();
635	    return;
636	  }
637	
638	  // When a thread successfully completes a target nowait region, we
639	  // exponentially backoff its query counter by the query factor.
640	  QueryCounter.decrement();
641	
642	  // Delete the handle and unset it from the OpenMP task data.
643	  delete AsyncInfo;
644	  *AsyncHandle = nullptr;
645	}
646	
647	EXTERN void __tgt_register_rpc_callback(unsigned (*Callback)(void *,
648	                                                             unsigned)) {
649	  if (!PM)
650	    return;
651	
652	  for (auto &Plugin : PM->plugins())
653	    if (Plugin.is_initialized() && Plugin.getNumDevices() > 0)
654	      Plugin.getRPCServer().registerCallback(Callback);
655	}
